// POJ 1341 - The Strongest Subchains
// Model: gpt-6.1-sol
// Sparse-table range minima answer each generated inclusive interval in O(1).
// Quadratics are generated by modular first and second differences, avoiding
// overflowing products. The formulas and example use zero-based indices,
// despite the contradictory one-based inequality in the statement.
#include <cstdio>
#include <algorithm>
using namespace std;
static int st[16][50000], lg[50001];
struct Generator {
    int value, delta, second, mod;
    Generator(int a, int b, int c, int m): mod(m) {
        value=c%m; delta=(a+b)%m; second=(2*a)%m;
    }
    int next() {
        int result=value;
        value=(value+delta)%mod;
        delta=(delta+second)%mod;
        return result;
    }
};
int main() {
    for(int i=2;i<=50000;++i) lg[i]=lg[i/2]+1;
    int w; if(scanf("%d",&w)!=1) return 0;
    while(w--) {
        int n,a,b,c,m,s1,s2,s3,e1,e2,e3;
        scanf("%d%d%d%d%d%d%d%d%d%d%d",&n,&a,&b,&c,&m,&s1,&s2,&s3,&e1,&e2,&e3);
        Generator values(a,b,c,9973), starts(s1,s2,s3,n/2), lengths(e1,e2,e3,n/2);
        for(int i=0;i<n;++i) st[0][i]=values.next();
        for(int k=1;(1<<k)<=n;++k)
            for(int i=0;i+(1<<k)<=n;++i)
                st[k][i]=min(st[k-1][i],st[k-1][i+(1<<(k-1))]);
        int best=-1, answer=0;
        for(int i=0;i<m;++i) {
            int left=starts.next(), right=left+lengths.next();
            int k=lg[right-left+1];
            int value=min(st[k][left],st[k][right-(1<<k)+1]);
            if(value>best) { best=value; answer=i; }
        }
        printf("%d\n",answer);
    }
    return 0;
}
